package fraymus.workspace;

import org.json.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;

/** Durable actual native trials, immutable decisions and reversible explicit activation. */
final class PushLearningStore implements AutoCloseable {
    private final Path root,file;private final LinkedHashMap<String,JSONObject> jobs=new LinkedHashMap<>();private JSONObject registry=new JSONObject().put("active","baseline-031").put("profiles",new JSONArray()).put("history",new JSONArray());
    private final ExecutorService worker=Executors.newSingleThreadExecutor(r->{var t=new Thread(r,"native-force-learning");t.setDaemon(true);return t;});private volatile boolean closed,stop;private volatile String active="";private volatile PushStore nativeOwner;
    PushLearningStore(Path project) throws Exception {root=project.resolve("push-learning");file=root.resolve("state.json");if(Files.exists(file)){var state=new JSONObject(Files.readString(file));registry=state.getJSONObject("registry");for(Object raw:state.getJSONArray("jobs")){var j=(JSONObject)raw;if(j.getString("status").equals("running"))j.put("status","interrupted").put("reason","Process ended; explicit Resume continues the frozen native trial and completed evidence");jobs.put(j.getString("id"),j);}}persist();}
    private synchronized void persist() throws Exception {atomic(file,new JSONObject().put("jobs",new JSONArray(jobs.values())).put("registry",registry));}
    static void atomic(Path path,JSONObject data) throws Exception {Files.createDirectories(path.getParent());var pending=path.resolveSibling(path.getFileName()+".pending");Files.writeString(pending,data.toString(),StandardCharsets.UTF_8);Files.move(pending,path,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
    synchronized boolean busy(){return !active.isEmpty();}
    synchronized JSONObject read(String id){var j=jobs.get(id);if(j==null)throw new IllegalArgumentException("Unknown force-learning job");return PushLearning.copy(j);}
    synchronized String status(String id){return jobs.get(id).getString("status");}
    synchronized JSONObject state(){var list=new JSONArray();for(var j:jobs.values())list.put(new JSONObject().put("id",j.getString("id")).put("status",j.getString("status")).put("completedTrials",j.getJSONArray("trials").length()).put("selection",j.optJSONObject("selection",new JSONObject())).put("decision",j.optJSONObject("decision",new JSONObject())));return new JSONObject().put("jobs",list).put("active",profile(registry.getString("active"))).put("history",registry.getJSONArray("history"));}
    private Path folder(String id){UUID.fromString(id);return root.resolve("jobs").resolve(id);}
    private void compatible(JSONObject j){if(!j.getString("codeSha256").equals(PushLearning.identity())||!j.getString("suiteSha256").equals(PushLearning.hash(PushLearning.suite()))||!j.getJSONObject("suite").similar(PushLearning.suite()))throw new IllegalStateException("Frozen learning suite/code changed; no replacement experiment started");}
    synchronized JSONObject start(String id,String goalId) throws Exception {if(jobs.containsKey(id))return read(id);if(closed||busy()||jobs.size()>=12)throw new IllegalStateException("Learning owner must be idle with history capacity");UUID.fromString(id);var suite=PushLearning.suite();var j=new JSONObject().put("id",id).put("goalId",goalId).put("suite",suite).put("suiteSha256",PushLearning.hash(suite)).put("codeSha256",PushLearning.identity()).put("status","running").put("createdAt",Instant.now()).put("trials",new JSONArray()).put("events",new JSONArray()).put("resumes",0);jobs.put(id,j);active=id;stop=false;persist();worker.submit(()->execute(id));return read(id);}
    synchronized JSONObject resume(String id) throws Exception {if(closed||busy())throw new IllegalStateException("Learning owner must be idle");var j=jobs.get(id);compatible(j);if(!j.getString("status").equals("interrupted")||j.optInt("resumes")>=3)throw new IllegalStateException("Resume an interrupted compatible learning job");j.put("resumes",j.getInt("resumes")+1).put("status","running");active=id;stop=false;persist();worker.submit(()->execute(id));return read(id);}
    synchronized JSONObject cancel(String id) throws Exception {var j=jobs.get(id);if(id.equals(active))stop=true;else if(j.getString("status").equals("interrupted"))j.put("status","cancelled");persist();return read(id);}
    private void execute(String id){try{JSONObject j;synchronized(this){j=jobs.get(id);compatible(j);}
        var suite=j.getJSONObject("suite");for(Object force:suite.getJSONArray("candidateInitialForcesN"))for(Object raw:PushLearning.cases(suite,"training"))trial(j,(JSONObject)raw,"training",((Number)force).doubleValue());
        synchronized(this){if(!j.has("selection")){j.put("selection",PushLearning.select(suite,j.getJSONArray("trials"))).put("selectionAfterTrial",j.getJSONArray("trials").length()).put("selectedAt",Instant.now());persist();}}
        double selected=j.getJSONObject("selection").getDouble("initialForceN");for(Object raw:PushLearning.cases(suite,"evaluation")){var c=(JSONObject)raw;trial(j,c,"baseline",suite.getDouble("baselineInitialForceN"));trial(j,c,"candidate",selected);}
        synchronized(this){if(stop||closed)throw new InterruptedException();var verified=verify(id);j.put("decision",verified).put("status","completed").put("completedAt",Instant.now());persist();}
    }catch(Exception e){synchronized(this){var j=jobs.get(id);j.put("status",stop?"cancelled":"interrupted").put("reason",String.valueOf(e.getMessage()));try{persist();}catch(Exception ignored){}}}finally{synchronized(this){active="";}}}
    private void trial(JSONObject j,JSONObject c,String arm,double force) throws Exception {
        if(stop||closed||Thread.currentThread().isInterrupted())throw new InterruptedException("Native learning stopped");String key=c.getString("id")+":"+arm+":"+force;String job=j.getString("id"),runId=UUID.nameUUIDFromBytes((job+":"+key).getBytes(StandardCharsets.UTF_8)).toString();Path dir=folder(job).resolve("native").resolve(runId);JSONObject plan=PushLearning.plan(j.getJSONObject("suite"),c,job,force);if(!plan.getBoolean("passed"))throw new IllegalStateException("Frozen case has no admitted standing plan: "+c.getString("id"));
        synchronized(this){for(Object raw:j.getJSONArray("trials"))if(((JSONObject)raw).getString("key").equals(key))return;j.put("current",new JSONObject().put("caseId",c.getString("id")).put("split",c.getString("split")).put("arm",arm).put("initialForceN",force).put("runId",runId));persist();}
        try(var nativeStore=new PushStore(dir)){nativeOwner=nativeStore;
            if(!nativeStore.hasRun(runId))nativeStore.start(runId,j.getString("goalId"),PushLearning.source(c,job),plan,false);
            else if(Set.of("paused","interrupted").contains(nativeStore.status(runId)))nativeStore.resume(runId,PushLearning.source(c,job),false);
            while(nativeStore.status(runId).equals("running")){if(stop||closed||Thread.currentThread().isInterrupted()){nativeStore.cancel(runId);throw new InterruptedException("Native learning interrupted");}Thread.sleep(5);}
            var run=nativeStore.run(runId);if(!Set.of("completed","failed").contains(run.getString("status")))throw new IllegalStateException("Native trial stopped: "+run.optString("reason"));var metrics=PushVerify.verify(run);Path result=dir.resolve("result.json");atomic(result,run);String rawSha=MapDefinition.sha(Files.readAllBytes(result));
            synchronized(this){if(stop||closed)throw new InterruptedException();j.getJSONArray("trials").put(new JSONObject().put("key",key).put("caseId",c.getString("id")).put("split",c.getString("split")).put("arm",arm).put("initialForceN",force).put("runId",runId).put("rawSha256",rawSha).put("nativeStatus",run.getString("status")).put("reason",run.optString("reason","")).put("metrics",metrics));j.getJSONArray("events").put(new JSONObject().put("kind","trial-completed").put("ordinal",j.getJSONArray("trials").length()).put("caseId",c.getString("id")).put("arm",arm));persist();}
        }
    }
    synchronized JSONObject live(){if(active.isEmpty()||nativeOwner==null)return new JSONObject();var j=jobs.get(active);var c=j.optJSONObject("current");if(c==null)return new JSONObject();var scene=PushLearning.source(PushLearning.find(j.getJSONObject("suite"),c.getString("caseId")),active);return new JSONObject().put("source",scene).put("currentTrial",c).put("snapshot",nativeOwner.snapshot());}
    synchronized JSONObject nativeRun(String id,String runId) throws Exception {UUID.fromString(runId);var j=read(id);for(Object raw:j.getJSONArray("trials"))if(((JSONObject)raw).getString("runId").equals(runId)){var t=(JSONObject)raw;Path path=folder(id).resolve("native").resolve(runId).resolve("result.json");if(!MapDefinition.sha(Files.readAllBytes(path)).equals(t.getString("rawSha256")))throw new IllegalStateException("Original native trial bytes changed");return new JSONObject(Files.readString(path));}throw new IllegalArgumentException("Native trial not committed");}
    synchronized JSONObject verify(String id) throws Exception {var j=jobs.get(id);compatible(j);var suite=j.getJSONObject("suite");var rows=j.getJSONArray("trials");int training=PushLearning.cases(suite,"training").length()*suite.getJSONArray("candidateInitialForcesN").length();if(j.getInt("selectionAfterTrial")!=training||rows.length()!=training+2*PushLearning.cases(suite,"evaluation").length())throw new IllegalStateException("Frozen split or trial count changed");var seen=new HashSet<String>();for(int i=0;i<rows.length();i++){var row=rows.getJSONObject(i);if(!seen.add(row.getString("key"))||i<training!=row.getString("split").equals("training"))throw new IllegalStateException("Selection chronology changed");var c=PushLearning.find(suite,row.getString("caseId"));if(!c.getString("split").equals(row.getString("split")))throw new IllegalStateException("Reserved case leaked into training");var run=nativeRun(id,row.getString("runId"));if(!run.getString("goalId").equals(j.getString("goalId"))||!run.getJSONObject("definition").similar(PushLearning.source(c,id))||!run.getJSONObject("plan").similar(PushLearning.plan(suite,c,id,row.getDouble("initialForceN")))||!PushVerify.verify(run).similar(row.getJSONObject("metrics")))throw new IllegalStateException("Native trial differs from original source/force/ledger");}return PushLearning.decide(suite,rows,j.getJSONObject("selection"));}
    synchronized JSONObject profile(String id){if(id.equals("baseline-031"))return new JSONObject().put("id",id).put("initialForceN",8).put("maxForceN",32).put("baseline",true);for(Object raw:registry.getJSONArray("profiles")){var p=(JSONObject)raw;if(p.getString("id").equals(id)){var checked=PushLearning.copy(p);String sha=checked.getString("sha256");checked.remove("sha256");if(!PushLearning.hash(checked).equals(sha))throw new IllegalStateException("Stored profile changed");return PushLearning.copy(p);}}throw new IllegalArgumentException("Unknown force profile");}
    synchronized JSONObject promote(String id,JSONObject receipt) throws Exception {var j=jobs.get(id);var decision=verify(id);if(!j.getString("status").equals("completed")||!decision.getBoolean("accepted")||!receipt.optBoolean("passed")||!j.has("viewReceipt")||!j.getJSONObject("viewReceipt").similar(receipt))throw new IllegalStateException("Promotion requires reserved gates and genuine verified report");String pid="force-"+id;boolean exists=false;for(Object raw:registry.getJSONArray("profiles"))if(((JSONObject)raw).getString("id").equals(pid))exists=true;if(!exists){var p=new JSONObject().put("id",pid).put("jobId",id).put("initialForceN",j.getJSONObject("selection").getDouble("initialForceN")).put("maxForceN",32).put("codeSha256",j.getString("codeSha256")).put("suiteSha256",j.getString("suiteSha256")).put("decisionSha256",PushLearning.hash(decision)).put("viewReceipt",receipt);p.put("sha256",PushLearning.hash(p));registry.getJSONArray("profiles").put(p);}String old=registry.getString("active");if(!old.equals(pid)){registry.getJSONArray("history").put(new JSONObject().put("kind","activate").put("from",old).put("to",pid).put("at",Instant.now()));registry.put("active",pid);persist();}return profile(pid);}
    synchronized void verifiedView(String id,JSONObject receipt) throws Exception {verify(id);jobs.get(id).put("viewReceipt",receipt);persist();}
    synchronized JSONObject activeProfile(){return profile(registry.getString("active"));}
    synchronized JSONObject rollback(String expected) throws Exception {if(!registry.getString("active").equals(expected))throw new IllegalStateException("Active profile changed; refresh before rollback");var history=registry.getJSONArray("history");if(history.isEmpty())throw new IllegalStateException("No activation to roll back");JSONObject activation=null;for(int i=history.length()-1;i>=0;i--)if(history.getJSONObject(i).getString("kind").equals("activate")&&history.getJSONObject(i).getString("to").equals(expected)){activation=history.getJSONObject(i);break;}if(activation==null)throw new IllegalStateException("No matching activation");String prior=activation.getString("from");profile(prior);registry.put("active",prior);history.put(new JSONObject().put("kind","rollback").put("from",expected).put("to",prior).put("at",Instant.now()));persist();return activeProfile();}
    @Override public void close(){closed=true;worker.shutdownNow();try{worker.awaitTermination(3,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}}
}
